export const GLOSSARY_SHARD = Object.freeze({"circulating-supply":{"slug":"circulating-supply","cat":"basics","en":"Circulating supply","contentLocale":"vi","term":"Nguồn cung lưu hành (Circulating supply)","aka":["cung lưu hành","circulating supply"],"short":"Nguồn cung lưu hành (circulating supply) là số lượng coin hoặc token đang thực sự có trên thị trường và có thể giao dịch, không tính phần bị khóa, chưa phát hành hoặc đã bị đốt.","body":[["Mỗi đồng ",["tiền mã hóa","cryptocurrency"]," thường có ba con số cung: nguồn cung lưu hành, tổng cung (total supply) và cung tối đa (max supply). Ví dụ ",["Bitcoin","bitcoin"]," có cung tối đa 21 triệu, nhưng lưu hành chỉ là số BTC đã được đào ra."],["Nguồn cung lưu hành là thành phần trong công thức ",["vốn hóa","market-capitalization"],". Khi nó tăng do mở khóa hoặc phát hành mới mà nhu cầu không đổi, giá mỗi token chịu áp lực giảm. Ngược lại, ",["đốt token","token-burn"]," hoặc khóa ",["staking","staking"]," dài hạn có thể làm lượng sẵn sàng để bán ít đi."],["Các trang dữ liệu không phải lúc nào cũng thống nhất cách tính. Token trong ví đội ngũ, quỹ dự trữ hay hợp đồng staking có thể được tính hoặc không. Hãy so sánh vài nguồn và đọc tài liệu ",["tokenomics","tokenomics"]," của dự án."]],"example":"Một token có cung tối đa 800 triệu, đang lưu hành 200 triệu ở giá 1,2 USDT, vốn hóa 240 triệu USDT. Tháng tới dự án mở khóa 40 triệu token, nâng nguồn cung lưu hành lên 240 triệu, tăng 20%. Nếu tổng giá trị thị trường vẫn ở 240 triệu USDT, giá sẽ còn 1 USDT. Nếu cùng lúc dự án đốt 10 triệu token, lưu hành còn 230 triệu và mức giá tương ứng là khoảng 1,04 USDT.","mistakes":["Nhầm nguồn cung lưu hành với cung tối đa khi tính vốn hóa.","Tin vào một nguồn dữ liệu duy nhất trong khi các trang có thể tính khác nhau.","Không để ý nguồn cung lưu hành tăng đều mỗi tháng vì lịch phát hành."],"faq":[{"q":"Nguồn cung lưu hành khác tổng cung thế nào?","a":"Tổng cung là số token đã được tạo ra trừ phần đã đốt, kể cả phần còn khóa. Nguồn cung lưu hành chỉ tính phần đang lưu thông trên thị trường."},{"q":"Vì sao nguồn cung lưu hành thay đổi?","a":"Nó thay đổi khi có token mới được đào hoặc phát hành, khi token bị khóa được mở, hoặc khi token bị đốt và rút khỏi thị trường."}],"title":"Nguồn cung lưu hành là gì? Circulating supply","description":"Circulating supply là gì, khác tổng cung và cung tối đa thế nào, và vì sao mở khóa token ảnh hưởng tới giá.","related":[["market-capitalization","Vốn hóa thị trường (Market cap)","Vốn hóa thị trường (market cap) của một đồng tiền mã hóa là giá hiện tại nhân với nguồn cung lưu hành, cho biết tổng giá trị thị trường đang định cho lượng coin đang lưu thông."],["fully-diluted-valuation","Định giá pha loãng hoàn toàn (FDV)","Định giá pha loãng hoàn toàn (FDV) là giá hiện tại của token nhân với tổng cung tối đa, cho biết dự án sẽ được định giá bao nhiêu nếu toàn bộ token đã được phát hành."],["token-unlock","Mở khóa token (Token unlock)","Mở khóa token (token unlock) là thời điểm một lượng token trước đây bị khóa theo lịch vesting được phép chuyển và bán, thường là phần của đội ngũ, nhà đầu tư hoặc quỹ dự án."],["token-burn","Đốt token (Token burn)","Đốt token (token burn) là việc gửi token tới một địa chỉ không ai có thể truy cập hoặc hủy chúng bằng hợp đồng, khiến lượng token đó bị loại vĩnh viễn khỏi nguồn cung."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"bear-market":{"slug":"bear-market","cat":"basics","en":"Bear market","contentLocale":"vi","term":"Thị trường giảm giá (Bear market)","aka":["bear market","thị trường gấu","downtrend","mùa đông crypto"],"short":"Thị trường giảm giá (bear market) là giai đoạn giá giảm kéo dài, thường hơn 20% từ đỉnh, kèm tâm lý bi quan, khối lượng giao dịch thấp và dòng tiền rút khỏi thị trường.","body":[["Trong crypto, thị trường gấu có thể kéo dài nhiều tháng và mức giảm thường sâu hơn thị trường truyền thống: ",["BTC","bitcoin"]," từng giảm hơn 70% từ đỉnh, nhiều ",["altcoin","altcoin"]," giảm trên 90% và không bao giờ hồi lại. Cộng đồng hay gọi giai đoạn này là mùa đông crypto."],"Thị trường giảm cũng có những đợt hồi mạnh khiến nhiều người tưởng đáy đã qua, rồi giá lại giảm tiếp. Đây là lúc các dự án yếu và sàn hoạt động kém thường lộ vấn đề.",["Cách người ta phản ứng khác nhau: có người mua định kỳ (",["DCA","dollar-cost-averaging"],") với tài sản họ tin tưởng dài hạn, có người giữ ",["stablecoin","stablecoin"],", có người ",["bán khống","short-selling"]," với quản lý rủi ro chặt. Quan trọng nhất là giữ đủ tiền mặt, không dùng tiền vay và không bắt dao rơi bằng ",["đòn bẩy","leverage"],"."]],"example":"Một altcoin giảm từ 10 USDT xuống 2 USDT, tức giảm 80%. Bạn mua 1.000 USDT ở 5 USDT vì nghĩ đã giảm một nửa là rẻ, nhận 200 token. Khi giá xuống 2 USDT, phần của bạn còn 400 USDT. Để về lại hòa vốn ở 5 USDT, giá cần tăng 150% từ 2 USDT. Nếu bạn chia 1.000 USDT thành 4 lần mua ở 5, 4, 3 và 2 USDT, mỗi lần 250 USDT, giá vốn trung bình của bạn khoảng 3,12 USDT.","mistakes":["Nghĩ rằng giá đã giảm 50% thì không thể giảm thêm.","Dùng đòn bẩy để bắt đáy trong khi xu hướng vẫn đi xuống.","Bán hoảng loạn toàn bộ ở đáy chỉ vì tin xấu trên mạng xã hội."],"faq":[{"q":"Thị trường gấu kéo dài bao lâu?","a":"Không có thời gian cố định. Trong lịch sử crypto, có giai đoạn kéo dài khoảng một năm hoặc hơn, nhưng quá khứ không đảm bảo cho tương lai."},{"q":"Có nên mua trong thị trường gấu?","a":"Đó là quyết định cá nhân. Nhiều người dùng chiến lược mua định kỳ số tiền nhỏ để không phải đoán đáy, và chỉ dùng tiền không cần đến trong ngắn hạn."}],"title":"Bear market là gì? Thị trường giảm giá crypto","description":"Bear market (thị trường gấu) là gì, vì sao crypto giảm sâu hơn chứng khoán và cách tránh sai lầm khi bắt đáy.","related":[["bull-market","Thị trường tăng giá (Bull market)","Thị trường tăng giá (bull market) là giai đoạn giá tài sản đi lên kéo dài, đi kèm tâm lý lạc quan, khối lượng giao dịch tăng và dòng tiền mới đổ vào thị trường."],["fud","FUD (sợ hãi, bất an, nghi ngờ)","FUD (Fear, Uncertainty, Doubt) là thông tin hoặc tâm lý gây sợ hãi, bất an và nghi ngờ về một dự án hay thị trường, có thể đúng sự thật hoặc bị phóng đại để làm giá giảm."],["dollar-cost-averaging","DCA (Trung bình giá)","DCA (dollar-cost averaging) là chiến lược mua một số tiền cố định của một tài sản theo lịch đều đặn, bất kể giá lên hay xuống, để làm mềm tác động của biến động giá."],["short-selling","Bán khống (Short selling)","Bán khống là việc bán một tài sản bạn không sở hữu, bằng cách vay hoặc dùng hợp đồng phái sinh, với kỳ vọng mua lại ở giá thấp hơn để kiếm lời."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"leverage":{"slug":"leverage","cat":"derivatives","en":"Leverage","contentLocale":"vi","term":"Đòn bẩy (Leverage)","aka":["leverage","đòn bẩy tài chính","x đòn bẩy"],"short":"Đòn bẩy là việc dùng một khoản ký quỹ nhỏ để mở vị thế có giá trị lớn hơn nhiều lần, làm phóng đại cả lợi nhuận lẫn thua lỗ.","body":[["Đòn bẩy 10x nghĩa là với 100 ",["USDT","usdt"]," ký quỹ, bạn mở vị thế trị giá 1.000 USDT. Mỗi 1% ",["biến động giá","volatility"]," tương đương 10% lãi hoặc lỗ trên ký quỹ. Đòn bẩy không thay đổi số tiền lãi lỗ tính theo giá trị vị thế; nó thay đổi lượng vốn bạn phải bỏ ra."],["Đòn bẩy càng cao, ",["giá thanh lý","liquidation-price"]," càng gần giá vào lệnh. Với 50x, giá chỉ cần đi ngược khoảng 2% trừ đi phần ",["ký quỹ duy trì","maintenance-margin"]," là vị thế có thể ",["bị thanh lý","liquidation"]," (cháy tài khoản). Đòn bẩy tối đa khác nhau theo sàn, ",["cặp giao dịch","trading-pair"],", quy mô vị thế và quy định từng quốc gia."],"Cách dùng đòn bẩy an toàn hơn là tính khối lượng vị thế theo cắt lỗ trước, rồi chọn đòn bẩy đủ để giá thanh lý nằm xa hơn cắt lỗ."],"example":"Giả sử bạn có 200 USDT và mở long BTC ở 80.000 USDT. Với đòn bẩy 5x, vị thế trị giá 1.000 USDT. Giá giảm 4% xuống 76.800 thì bạn lỗ 40 USDT, tức 20% ký quỹ. Với đòn bẩy 25x, vị thế trị giá 5.000 USDT, cùng mức giảm 4% làm bạn lỗ 200 USDT, gần như toàn bộ ký quỹ, và vị thế thường đã bị thanh lý trước đó.","mistakes":["Chọn đòn bẩy tối đa chỉ vì sàn cho phép.","Nghĩ rằng đòn bẩy thấp nghĩa là an toàn dù vị thế vẫn quá lớn so với tài khoản.","Không kiểm tra giá thanh lý sau khi đổi đòn bẩy."],"faq":[{"q":"Đòn bẩy bao nhiêu là an toàn?","a":"Không có mức an toàn tuyệt đối. Nhiều người giao dịch giữ đòn bẩy thấp, ví dụ 2-5x, và quan trọng hơn là giới hạn số tiền rủi ro mỗi lệnh."},{"q":"Đòn bẩy 100x nghĩa là gì?","a":"Bạn mở vị thế gấp 100 lần ký quỹ. Giá chỉ cần đi ngược dưới 1% là vị thế có thể bị thanh lý."}],"title":"Đòn bẩy là gì? Cách đòn bẩy hoạt động trong crypto","description":"Đòn bẩy trong crypto là gì, cách nó phóng đại lãi lỗ, ảnh hưởng đến giá thanh lý và cách chọn đòn bẩy hợp lý.","related":[["margin-trading","Giao dịch ký quỹ (Margin trading)","Giao dịch ký quỹ là việc vay thêm vốn từ sàn, dùng tài sản của bạn làm tài sản đảm bảo, để mở vị thế lớn hơn số tiền bạn có."],["liquidation-price","Giá thanh lý (Liquidation price)","Giá thanh lý là mức giá đánh dấu mà tại đó vị thế có đòn bẩy của bạn sẽ bị sàn tự động đóng do ký quỹ không còn đủ."],["initial-margin","Ký quỹ ban đầu (Initial margin)","Ký quỹ ban đầu là số tiền tối thiểu bạn phải đặt cọc để mở một vị thế có đòn bẩy, bằng giá trị vị thế chia cho đòn bẩy."],["isolated-margin","Ký quỹ cô lập (Isolated margin)","Ký quỹ cô lập là chế độ trong đó mỗi vị thế có một khoản ký quỹ riêng, nên nếu bị thanh lý bạn chỉ mất phần ký quỹ đã gán cho vị thế đó."],["position-sizing","Quản lý khối lượng vị thế (Position sizing)","Position sizing là cách xác định bạn nên mở một lệnh lớn bao nhiêu, dựa trên số tiền bạn chấp nhận mất nếu lệnh chạm cắt lỗ."]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"Đòn bẩy 10x: tiền nhiều hơn hay rủi ro lớn hơn?"},"coin":null,"tool":"/liquidations","cta":true},"auto-deleveraging":{"slug":"auto-deleveraging","cat":"derivatives","en":"Auto-deleveraging (ADL)","contentLocale":"vi","term":"Giảm đòn bẩy tự động (ADL)","aka":["ADL","auto-deleveraging","tự động giảm đòn bẩy"],"short":"Giảm đòn bẩy tự động (ADL) là cơ chế cuối cùng của sàn: khi quỹ bảo hiểm không đủ bù lỗ từ một vị thế bị thanh lý, sàn tự đóng một phần vị thế đang lãi ở phía đối diện.","body":[["Bình thường, khi một vị thế ",["bị thanh lý","liquidation"]," ở giá tệ hơn giá phá sản, ",["quỹ bảo hiểm","insurance-fund"]," bù phần thiếu. Nếu thị trường ",["biến động","volatility"]," quá mạnh và quỹ không đủ, sàn chọn các vị thế đối ứng đang lãi để đóng bớt theo giá phá sản của vị thế bị thanh lý."],["Thứ tự ưu tiên thường dựa trên mức lãi và ",["đòn bẩy","leverage"],": vị thế lãi nhiều và dùng đòn bẩy cao bị chọn trước. Nhiều sàn hiển thị chỉ báo hàng đợi ADL, ví dụ bằng các vạch đèn, để bạn biết vị thế của mình đứng ở đâu."],"ADL không làm bạn lỗ, nhưng vị thế đang lãi bị đóng sớm ngoài ý muốn, có thể đúng lúc thị trường đang có lợi cho bạn. Sàn có quỹ bảo hiểm lớn thường ít phải dùng ADL hơn, nhưng không có sàn nào loại trừ hoàn toàn."],"example":["Giả sử bạn short 5 SOL ở 200 ",["USDT","usdt"]," với đòn bẩy 20x và giá giảm về 150, bạn đang lãi 250 USDT. Thị trường sập mạnh, nhiều ",["vị thế long","long-and-short"]," bị thanh lý ở giá tệ, và quỹ bảo hiểm của cặp này cạn. Vị thế của bạn đứng đầu hàng đợi ADL, nên sàn đóng 3 SOL ở giá phá sản 152 của vị thế long đối ứng. Bạn chốt được 3 × 48 = 144 USDT trên phần đó, 2 SOL còn lại vẫn mở."],"mistakes":["Không biết ADL tồn tại và bất ngờ khi vị thế lãi bị đóng.","Giữ vị thế lãi lớn với đòn bẩy cao mà không xem chỉ báo hàng đợi ADL.","Nhầm ADL với thanh lý thông thường."],"faq":[{"q":"ADL là gì?","a":"Là cơ chế sàn đóng một phần vị thế đang lãi khi quỹ bảo hiểm không đủ bù lỗ thanh lý. Vị thế lãi nhiều, đòn bẩy cao thường bị chọn trước."},{"q":"Bị ADL có mất tiền không?","a":"Bạn không bị lỗ vì ADL, phần lãi được chốt theo giá của lệnh đối ứng. Nhưng bạn mất phần lợi nhuận có thể có nếu giữ tiếp."}],"title":"ADL là gì? Cơ chế giảm đòn bẩy tự động","description":"Giảm đòn bẩy tự động (ADL) là gì, khi nào sàn đóng vị thế đang lãi của bạn và cách đọc chỉ báo hàng đợi ADL.","related":[["insurance-fund","Quỹ bảo hiểm (Insurance fund)","Quỹ bảo hiểm là khoản dự trữ của sàn dùng để bù phần lỗ khi một vị thế bị thanh lý ở giá tệ hơn giá phá sản, nhằm tránh chuyển khoản lỗ đó sang người giao dịch khác."],["liquidation","Thanh lý (Liquidation)","Thanh lý (hay cháy tài khoản) là khi sàn tự động đóng vị thế có đòn bẩy của bạn vì ký quỹ không còn đủ đáp ứng mức ký quỹ duy trì."],["unrealized-pnl","Lãi lỗ chưa thực hiện (Unrealized PnL)","Lãi lỗ chưa thực hiện (unrealized PnL) là khoản lãi hoặc lỗ trên giấy của một vị thế đang mở, tính theo giá hiện tại, và chỉ trở thành lãi lỗ thật khi bạn đóng vị thế."],["leverage","Đòn bẩy (Leverage)","Đòn bẩy là việc dùng một khoản ký quỹ nhỏ để mở vị thế có giá trị lớn hơn nhiều lần, làm phóng đại cả lợi nhuận lẫn thua lỗ."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Thanh lý: ai đã nhấn nút buộc đóng vị thế?"},"coin":null,"tool":"/liquidations","cta":false},"crypto-wallet":{"slug":"crypto-wallet","cat":"wallets-security","en":"Crypto wallet","contentLocale":"vi","term":"Ví tiền mã hóa (Crypto wallet)","aka":["ví crypto","ví tiền điện tử","crypto wallet","ví coin"],"short":"Ví tiền mã hóa là phần mềm hoặc thiết bị quản lý khóa riêng tư của bạn, cho phép bạn nhận, gửi và ký giao dịch với tài sản crypto trên blockchain.","body":[["Coin không thực sự nằm trong ví mà nằm trên ",["blockchain","blockchain"],". Ví giữ ",["khóa riêng tư","private-key"],", thứ chứng minh bạn có quyền điều khiển các địa chỉ đó. Ai có khóa riêng tư hoặc ",["cụm từ khôi phục (seed phrase)","seed-phrase"]," thì có quyền chuyển tài sản đi."],["Có hai nhóm chính. ",["Ví lưu ký","custodial-wallet"]," (custodial) như tài khoản trên ",["sàn tập trung","centralized-exchange"],": sàn giữ khóa, bạn đăng nhập bằng tài khoản. ",["Ví tự lưu ký","non-custodial-wallet"]," (non-custodial) như ví phần mềm trên điện thoại, tiện ích trình duyệt hay ví cứng: bạn tự giữ khóa và tự chịu trách nhiệm."],"Ví còn phân thành ví nóng (kết nối internet, tiện lợi) và ví lạnh (ngoại tuyến, an toàn hơn cho số lượng lớn). Mỗi ví hỗ trợ các blockchain khác nhau, nên hãy kiểm tra ví có hỗ trợ đúng mạng lưới trước khi nhận tiền."],"example":"Giả sử bạn giữ 1.500 USDT trên sàn để giao dịch và 0,2 BTC để giữ lâu dài. Bạn có thể để 1.500 USDT trong ví lưu ký của sàn cho tiện, và chuyển 0,2 BTC sang ví tự lưu ký. Khi rút BTC, bạn trả phí mạng, ví dụ 0,0002 BTC, nên ví nhận khoảng 0,1998 BTC. Từ lúc này, chỉ cụm từ khôi phục 12 hoặc 24 từ của bạn mới khôi phục được ví đó.","mistakes":["Chụp ảnh hoặc lưu cụm từ khôi phục trên điện thoại, email hay dịch vụ đám mây.","Gửi coin trên một mạng lưới mà ví nhận không hỗ trợ.","Nghĩ rằng gỡ ứng dụng ví là mất coin, trong khi coin vẫn nằm trên blockchain và khôi phục được bằng seed phrase."],"faq":[{"q":"Ví crypto là gì?","a":"Là công cụ giữ khóa riêng tư để bạn quản lý tài sản trên blockchain. Coin nằm trên blockchain, ví chỉ giữ quyền điều khiển."},{"q":"Nên dùng ví nào cho người mới?","a":"Người mới thường bắt đầu với ví trên sàn để giao dịch, rồi học cách dùng ví tự lưu ký cho phần tài sản giữ lâu. Quan trọng nhất là bảo quản seed phrase ngoại tuyến."}],"title":"Ví crypto là gì? Các loại ví tiền mã hóa","description":"Ví tiền mã hóa là gì, khác biệt giữa ví lưu ký và tự lưu ký, ví nóng và ví lạnh, và cách giữ seed phrase an toàn.","related":[["custodial-wallet","Ví lưu ký (Custodial wallet)","Ví lưu ký là ví mà một bên thứ ba, thường là sàn giao dịch, giữ khóa riêng tư thay bạn; bạn truy cập tài sản bằng tài khoản và mật khẩu thay vì seed phrase."],["non-custodial-wallet","Ví phi lưu ký (Non-custodial wallet)","Ví phi lưu ký là loại ví crypto mà bạn tự giữ khóa riêng tư và cụm từ khôi phục, nên chỉ bạn mới có quyền ký giao dịch và di chuyển tài sản."],["seed-phrase","Cụm từ khôi phục (Seed phrase)","Cụm từ khôi phục là chuỗi 12 hoặc 24 từ tiếng Anh dùng để tạo lại toàn bộ khóa riêng tư của ví, nên ai có nó là có toàn quyền với tài sản trong ví."],["wallet-address","Địa chỉ ví (Wallet address)","Địa chỉ ví là chuỗi ký tự công khai đại diện cho nơi nhận crypto trên một blockchain cụ thể, giống số tài khoản ngân hàng nhưng gắn với từng mạng lưới."],["hardware-wallet","Ví cứng (Hardware wallet)","Ví cứng là thiết bị vật lý nhỏ chuyên lưu khóa riêng tư ngoại tuyến và ký giao dịch bên trong thiết bị, nên khóa không bao giờ lộ ra máy tính hay điện thoại."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin của tôi ở đâu: Sàn giao dịch và ví khác nhau thế nào?"},"coin":null,"tool":null,"cta":false},"memo-tag":{"slug":"memo-tag","cat":"wallets-security","en":"Memo / destination tag","contentLocale":"vi","term":"Memo / Tag (Destination tag)","aka":["memo","tag","destination tag","MEMO"],"short":"Memo hay tag là mã bổ sung đi kèm địa chỉ ví trên một số blockchain như XRP, XLM, TON, ATOM, giúp sàn biết khoản nạp vào địa chỉ chung thuộc về tài khoản nào.","body":[["Với một số coin, sàn dùng một ",["địa chỉ nạp","wallet-address"]," chung cho rất nhiều khách hàng. Địa chỉ chỉ đưa tiền vào ví của sàn, còn memo hoặc destination tag mới cho hệ thống biết ghi có cho ai. Tên gọi khác nhau tùy mạng: XRP gọi là Destination Tag, Stellar, TON hay Cosmos thường gọi là Memo."],["Khi nạp ",["lên sàn","token-listing"]," mà trang nạp hiển thị cả địa chỉ lẫn memo, bạn bắt buộc phải điền cả hai. Thiếu hoặc sai memo, tiền vẫn đến ví của sàn nhưng không vào tài khoản của bạn, và thường phải làm đơn khiếu nại, chờ lâu, có thể mất phí."],"Khi gửi đến ví cá nhân của chính bạn, thường không cần memo. Quy tắc đơn giản: nếu bên nhận có yêu cầu memo thì phải điền, nếu không thì để trống."],"example":"Giả sử bạn rút 500 XRP từ sàn A sang sàn B. Trang nạp của sàn B ghi địa chỉ rXk…9Lp và Destination Tag 104857. Bạn dán địa chỉ, nhập 104857 vào ô Tag, gửi thử 20 XRP trước. Sau khi thấy 20 XRP vào tài khoản sàn B, bạn gửi 480 XRP còn lại với cùng tag. Nếu quên tag, 500 XRP vẫn nằm ở ví sàn B nhưng bạn phải gửi yêu cầu hỗ trợ để được ghi có.","mistakes":["Bỏ trống memo vì nghĩ nó không bắt buộc, trong khi sàn nhận có yêu cầu.","Dùng lại memo cũ của một sàn khác hoặc tài khoản khác.","Nhập memo vào ô ghi chú cá nhân thay vì đúng ô Memo/Tag trên form rút."],"faq":[{"q":"Quên điền memo khi nạp thì có mất tiền không?","a":"Thường không mất hẳn vì tiền đã về ví của sàn, nhưng bạn phải liên hệ hỗ trợ kèm mã giao dịch để họ ghi có thủ công. Thời gian và phí xử lý tùy sàn."},{"q":"Coin nào cần memo hoặc tag?","a":"Phổ biến là XRP, XLM, TON, ATOM, EOS và một số coin khác khi nạp lên sàn. Hãy luôn xem trang nạp của sàn để biết chính xác."}],"title":"Memo, tag là gì? Khi nào cần điền khi nạp coin","description":"Memo/tag là gì, vì sao sàn yêu cầu khi nạp XRP, XLM, TON, ATOM và cách xử lý nếu bạn quên điền memo.","related":[["wallet-address","Địa chỉ ví (Wallet address)","Địa chỉ ví là chuỗi ký tự công khai đại diện cho nơi nhận crypto trên một blockchain cụ thể, giống số tài khoản ngân hàng nhưng gắn với từng mạng lưới."],["blockchain-network","Mạng nạp rút (Chọn mạng blockchain)","Mạng nạp rút là blockchain cụ thể mà một đồng coin được chuyển qua, ví dụ USDT có thể đi trên Tron (TRC20), Ethereum (ERC20) hay BNB Chain (BEP20); bên gửi và bên nhận phải dùng cùng mạng."],["transaction-hash","Mã giao dịch (Transaction hash, TxID)","Mã giao dịch (TxID hay TxHash) là chuỗi ký tự duy nhất định danh một giao dịch trên blockchain, dùng để tra cứu trạng thái, số tiền, phí và số xác nhận của giao dịch đó."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Trước khi chuyển coin: Tuyệt đối không đoán mò những điểm này"},"coin":null,"tool":null,"cta":false},"two-factor-authentication":{"slug":"two-factor-authentication","cat":"wallets-security","en":"Two-factor authentication (2FA)","contentLocale":"vi","term":"Xác thực hai yếu tố (2FA)","aka":["2FA","xác thực 2 lớp","Google Authenticator","bảo mật 2 lớp"],"short":"Xác thực hai yếu tố (2FA) là lớp bảo mật yêu cầu thêm một mã hoặc thiết bị ngoài mật khẩu khi đăng nhập, rút tiền hay đổi cài đặt, để kẻ chỉ có mật khẩu vẫn không vào được tài khoản.","body":["Trên sàn crypto, 2FA thường có các dạng: mã SMS, mã email, ứng dụng tạo mã 6 số thay đổi mỗi 30 giây như Google Authenticator, và khóa bảo mật vật lý hoặc passkey. Mã từ ứng dụng hoặc khóa vật lý an toàn hơn SMS, vì số điện thoại có thể bị chiếm qua lừa nhà mạng đổi SIM.","Sàn thường yêu cầu 2FA cho đăng nhập, rút tiền, tạo API key và thay đổi bảo mật. Sau khi bạn đổi phương thức 2FA hay mật khẩu, nhiều sàn tạm khóa rút trong một khoảng thời gian để bảo vệ bạn.",["Khi bật 2FA bằng ứng dụng, hãy lưu lại khóa dự phòng (backup key) ngoại tuyến. Mất điện thoại mà không có khóa này, bạn phải qua quy trình ",["xác minh danh tính","kyc"]," lâu hơn để khôi phục."]],"example":["Giả sử mật khẩu sàn của bạn bị lộ trong một vụ rò rỉ dữ liệu ở trang web khác. Kẻ gian đăng nhập và thử rút 2.500 ",["USDT","usdt"],". Sàn yêu cầu mã 6 số từ ứng dụng xác thực trên điện thoại của bạn, mã đổi mỗi 30 giây. Không có điện thoại, chúng không rút được. Bạn nhận email cảnh báo đăng nhập lạ, đổi mật khẩu ngay và số dư vẫn nguyên 2.500 USDT."],"mistakes":["Chỉ dùng 2FA qua SMS cho tài khoản có số dư lớn.","Đọc mã 2FA cho người tự xưng là nhân viên sàn qua điện thoại hoặc Telegram.","Không lưu khóa dự phòng khi thiết lập ứng dụng xác thực rồi bị mất điện thoại."],"faq":[{"q":"Nên dùng 2FA loại nào cho sàn crypto?","a":"Ứng dụng xác thực hoặc khóa bảo mật vật lý, passkey thường an toàn hơn SMS. Bạn có thể bật nhiều phương thức cùng lúc nếu sàn hỗ trợ."},{"q":"Mất điện thoại có ứng dụng 2FA thì làm sao?","a":"Dùng khóa dự phòng đã lưu để cài lại trên máy mới. Nếu không có, hãy liên hệ sàn để làm thủ tục đặt lại 2FA, thường cần xác minh danh tính."}],"title":"2FA là gì? Xác thực hai yếu tố trên sàn crypto","description":"Xác thực hai yếu tố (2FA) là gì, các loại 2FA trên sàn crypto, loại nào an toàn nhất và xử lý khi mất điện thoại.","related":[["anti-phishing-code","Mã chống lừa đảo (Anti-phishing code)","Mã chống lừa đảo là chuỗi ký tự riêng bạn tự đặt trên sàn, sau đó sàn chèn nó vào mọi email chính thức để bạn phân biệt email thật với email giả mạo."],["withdrawal-whitelist","Danh sách trắng rút tiền (Withdrawal whitelist)","Danh sách trắng rút tiền là tính năng bảo mật chỉ cho phép tài khoản sàn rút crypto đến những địa chỉ bạn đã lưu và xác minh trước."],["phishing","Lừa đảo giả mạo (Phishing)","Phishing là hình thức lừa đảo giả mạo sàn, ví, dự án hoặc người quen để lừa bạn nhập mật khẩu, mã 2FA, cụm từ khôi phục hoặc ký giao dịch có hại."],["sub-account","Tài khoản phụ (sub-account)","Tài khoản phụ là tài khoản con được tạo dưới tài khoản chính trên sàn, có số dư và vị thế riêng, giúp bạn tách biệt chiến lược, rủi ro và quyền truy cập."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Tìm đúng cửa chính thức: Đừng mở tài khoản một cách mù quáng"},"coin":null,"tool":null,"cta":false},"withdrawal-whitelist":{"slug":"withdrawal-whitelist","cat":"wallets-security","en":"Withdrawal whitelist","contentLocale":"vi","term":"Danh sách trắng rút tiền (Withdrawal whitelist)","aka":["whitelist rút tiền","withdrawal whitelist","danh sách địa chỉ tin cậy"],"short":"Danh sách trắng rút tiền là tính năng bảo mật chỉ cho phép tài khoản sàn rút crypto đến những địa chỉ bạn đã lưu và xác minh trước.","body":[["Khi bật whitelist, mọi lệnh rút đến địa chỉ ngoài danh sách sẽ bị chặn. Muốn thêm địa chỉ mới, bạn phải xác minh bằng ",["2FA","two-factor-authentication"],", email, và nhiều sàn còn áp thời gian chờ, ví dụ 24 giờ, trước khi địa chỉ mới dùng được."],["Lợi ích chính: ngay cả khi kẻ gian đăng nhập được tài khoản, chúng khó rút tiền về ví của chúng. Tính năng cũng giảm rủi ro dán nhầm địa chỉ hoặc dính tấn công ",["đầu độc địa chỉ","address-poisoning"],", vì bạn chọn từ danh sách đã kiểm tra."],"Nhược điểm là kém linh hoạt khi cần gửi gấp đến địa chỉ mới. Cách áp dụng, thời gian chờ và việc có bắt buộc gắn mạng với địa chỉ hay không khác nhau giữa các sàn."],"example":["Giả sử bạn bật whitelist và chỉ lưu hai địa chỉ: ",["ví cứng","hardware-wallet"]," của bạn và tài khoản sàn thứ hai. Một ngày kẻ gian chiếm được phiên đăng nhập và cố rút 3.000 ",["USDT","usdt"]," đến địa chỉ lạ. Sàn từ chối vì địa chỉ không nằm trong danh sách. Chúng thử thêm địa chỉ mới nhưng cần mã 2FA và phải chờ 24 giờ, đủ để bạn nhận email cảnh báo và khóa tài khoản."],"mistakes":["Thêm địa chỉ vào whitelist bằng cách sao chép từ lịch sử giao dịch mà không đối chiếu nguồn gốc.","Đặt nhãn mơ hồ cho địa chỉ khiến sau này chọn nhầm ví.","Tắt whitelist vĩnh viễn chỉ vì một lần cần rút gấp."],"faq":[{"q":"Có nên bật whitelist rút tiền không?","a":"Với tài khoản có số dư đáng kể và ít đổi địa chỉ nhận, bật whitelist là lớp bảo vệ rất hiệu quả. Nó chỉ bất tiện khi bạn thường xuyên gửi đến địa chỉ mới."},{"q":"Whitelist có thay thế 2FA được không?","a":"Không. Whitelist bảo vệ khâu rút tiền, còn 2FA bảo vệ đăng nhập và thay đổi cài đặt; nên dùng cả hai."}],"title":"Whitelist rút tiền là gì? Cách bảo vệ tài khoản sàn","description":"Danh sách trắng rút tiền là gì, cách hoạt động trên sàn crypto, lợi ích bảo mật và những lưu ý khi thêm địa chỉ mới.","related":[["wallet-address","Địa chỉ ví (Wallet address)","Địa chỉ ví là chuỗi ký tự công khai đại diện cho nơi nhận crypto trên một blockchain cụ thể, giống số tài khoản ngân hàng nhưng gắn với từng mạng lưới."],["two-factor-authentication","Xác thực hai yếu tố (2FA)","Xác thực hai yếu tố (2FA) là lớp bảo mật yêu cầu thêm một mã hoặc thiết bị ngoài mật khẩu khi đăng nhập, rút tiền hay đổi cài đặt, để kẻ chỉ có mật khẩu vẫn không vào được tài khoản."],["address-poisoning","Đầu độc địa chỉ (Address poisoning)","Đầu độc địa chỉ là chiêu lừa đảo gửi giao dịch nhỏ từ một địa chỉ có đầu và cuối giống địa chỉ bạn hay dùng, để bạn sao chép nhầm từ lịch sử giao dịch và chuyển tiền cho kẻ gian."],["anti-phishing-code","Mã chống lừa đảo (Anti-phishing code)","Mã chống lừa đảo là chuỗi ký tự riêng bạn tự đặt trên sàn, sau đó sàn chèn nó vào mọi email chính thức để bạn phân biệt email thật với email giả mạo."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Trước khi chuyển coin: Tuyệt đối không đoán mò những điểm này"},"coin":null,"tool":null,"cta":false},"crypto-backed-stablecoin":{"slug":"crypto-backed-stablecoin","cat":"stablecoins","en":"Crypto-backed stablecoin","contentLocale":"vi","term":"Stablecoin thế chấp bằng crypto","aka":["stablecoin thế chấp crypto","crypto-backed stablecoin","stablecoin phi tập trung"],"short":"Stablecoin thế chấp bằng crypto là stablecoin được đúc ra khi người dùng khóa tài sản crypto như ETH vào hợp đồng thông minh với giá trị lớn hơn số stablecoin nhận được.","body":[["Khác với ",["USDT","usdt"]," hay ",["USDC","usdc"]," dựa vào tiền và trái phiếu trong ngân hàng, loại ",["stablecoin","stablecoin"]," này dựa vào tài sản crypto nằm trên chuỗi. Ví dụ quen thuộc là DAI của MakerDAO, nay thuộc hệ sinh thái Sky. Vì crypto ",["biến động","volatility"]," mạnh, hệ thống yêu cầu thế chấp vượt mức, thường từ 150% trở lên tùy loại tài sản."],["Người dùng mở một vị thế vay: khóa ",["ETH","ethereum"],", đúc ra stablecoin để dùng. Nếu giá ETH giảm và tỷ lệ thế chấp rơi xuống dưới ngưỡng, vị thế ",["bị thanh lý","liquidation"],": tài sản thế chấp được bán đấu giá để trả nợ, kèm một khoản phạt."],"Ưu điểm là minh bạch, ai cũng kiểm tra được dự trữ trên chuỗi. Nhược điểm là kém hiệu quả về vốn và phụ thuộc vào oracle giá. Một số giao thức hiện còn thêm cả USDC hay tài sản thực vào dự trữ, nên mức độ phi tập trung khác nhau."],"example":"Giả sử ETH giá 3.000 USD và giao thức yêu cầu tỷ lệ thế chấp tối thiểu 150%. Bạn khóa 2 ETH, tức 6.000 USD, và đúc 3.000 stablecoin. Tỷ lệ lúc này là 200%. Nếu ETH giảm xuống 2.250 USD, tài sản thế chấp còn 4.500 USD, đúng bằng 150% của 3.000, và vị thế chạm ngưỡng thanh lý. Để an toàn, bạn có thể nạp thêm ETH hoặc trả bớt nợ trước khi giá tới mức đó.","mistakes":["Đúc stablecoin sát ngưỡng thanh lý để tối đa số tiền vay, chỉ một cú giảm nhẹ là mất tài sản thế chấp.","Quên rằng ngoài nợ gốc còn có phí ổn định cộng dồn theo thời gian.","Tin rằng cứ thế chấp crypto là hoàn toàn phi tập trung, trong khi dự trữ có thể chứa cả stablecoin tập trung."],"faq":[{"q":"DAI có phải là stablecoin thế chấp bằng crypto không?","a":"Có, DAI ra đời như một stablecoin thế chấp vượt mức bằng crypto trên Ethereum. Theo thời gian, dự trữ của nó đã bổ sung cả stablecoin khác và tài sản thực."},{"q":"Vì sao phải thế chấp nhiều hơn số tiền vay?","a":"Vì giá crypto có thể giảm mạnh trong thời gian ngắn. Phần thế chấp dư là vùng đệm để hệ thống kịp thanh lý trước khi khoản nợ thiếu tài sản bảo đảm."}],"title":"Stablecoin thế chấp bằng crypto là gì? Cách DAI hoạt động","description":"Hiểu stablecoin thế chấp bằng crypto: thế chấp vượt mức, ngưỡng thanh lý, ví dụ tính toán và rủi ro khi đúc stablecoin.","related":[["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC."],["defi-lending","Cho vay DeFi (DeFi lending)","Cho vay DeFi là việc gửi crypto vào giao thức như Aave để nhận lãi, hoặc thế chấp crypto để vay tài sản khác, toàn bộ do hợp đồng thông minh quản lý thay cho ngân hàng."],["liquidation","Thanh lý (Liquidation)","Thanh lý (hay cháy tài khoản) là khi sàn tự động đóng vị thế có đòn bẩy của bạn vì ký quỹ không còn đủ đáp ứng mức ký quỹ duy trì."],["algorithmic-stablecoin","Stablecoin thuật toán","Stablecoin thuật toán là stablecoin cố giữ giá 1 USD chủ yếu bằng quy tắc phát hành và đốt token tự động, thay vì có đủ tài sản dự trữ bảo chứng phía sau."]],"lesson":null,"coin":{"slug":"dai","name":"Dai","symbol":"DAI"},"tool":null,"cta":false},"block-explorer":{"slug":"block-explorer","cat":"onchain","en":"Block explorer","contentLocale":"vi","term":"Block explorer (trình khám phá khối)","aka":["block explorer","trình duyệt blockchain","explorer"],"short":"Block explorer là trang web cho phép bạn tra cứu mọi giao dịch, địa chỉ ví và khối trên một blockchain, giống như công cụ tra cứu sao kê công khai của mạng đó.","body":[["Mỗi ",["blockchain","blockchain"]," có explorer riêng: Etherscan cho ",["Ethereum","ethereum"],", BscScan cho BNB Chain, Tronscan cho TRON, Solscan cho Solana, và nhiều explorer cho ",["Bitcoin","bitcoin"],". Bạn chỉ cần dán ",["mã giao dịch","transaction-hash"]," (TxID hay hash) hoặc ",["địa chỉ ví","wallet-address"]," vào ô tìm kiếm."],["Explorer cho biết giao dịch đã thành công, thất bại hay còn chờ, đã có bao nhiêu ",["xác nhận","block-confirmations"],", phí gas là bao nhiêu, ví nhận là ví nào và token gì đã được chuyển. Đây là công cụ quan trọng nhất khi tiền rút từ sàn chưa về ví."],"Hãy chú ý chọn đúng explorer của đúng mạng. Một giao dịch USDT trên TRON sẽ không bao giờ hiện trên Etherscan. Ngoài ra, cẩn thận với trang explorer giả mạo yêu cầu kết nối ví: explorer thật chỉ để tra cứu, không cần bạn ký gì."],"example":"Giả sử bạn rút 500 USDT từ sàn qua mạng TRC20 nhưng sau 20 phút vẫn chưa thấy trong ví. Bạn lấy TxID trong lịch sử rút tiền, dán vào Tronscan. Kết quả hiện trạng thái thành công, địa chỉ nhận khớp với ví của bạn, số lượng 499 USDT sau khi trừ 1 USDT phí rút. Vậy tiền đã đến nơi; có thể ví của bạn chỉ chưa hiện token USDT và cần thêm token đó vào danh sách hiển thị.","mistakes":["Tra mã giao dịch trên explorer của mạng khác rồi kết luận giao dịch không tồn tại.","Kết nối ví hoặc ký giao dịch trên trang tự xưng là explorer.","Gửi TxID cho người lạ tự nhận là hỗ trợ viên mà không tự kiểm tra trước."],"faq":[{"q":"TxID là gì và tìm ở đâu?","a":"TxID hay transaction hash là mã định danh duy nhất của một giao dịch. Bạn tìm thấy nó trong lịch sử rút tiền của sàn hoặc trong lịch sử giao dịch của ví."},{"q":"Explorer báo thành công nhưng ví không thấy tiền thì sao?","a":"Hãy kiểm tra ví đang xem đúng mạng và đã thêm token chưa. Nếu gửi lên sàn, hãy xem sàn có yêu cầu memo hay đủ số xác nhận chưa rồi liên hệ hỗ trợ chính thức."}],"title":"Block explorer là gì? Cách tra cứu giao dịch crypto","description":"Block explorer giúp tra cứu giao dịch, ví và khối trên blockchain. Hướng dẫn dùng TxID để kiểm tra tiền đã đến hay chưa.","related":[["transaction-hash","Mã giao dịch (Transaction hash, TxID)","Mã giao dịch (TxID hay TxHash) là chuỗi ký tự duy nhất định danh một giao dịch trên blockchain, dùng để tra cứu trạng thái, số tiền, phí và số xác nhận của giao dịch đó."],["block-confirmations","Số xác nhận khối (Block confirmations)","Số xác nhận khối là số khối đã được thêm vào blockchain kể từ khối chứa giao dịch của bạn; càng nhiều xác nhận thì giao dịch càng khó bị đảo ngược."],["wallet-address","Địa chỉ ví (Wallet address)","Địa chỉ ví là chuỗi ký tự công khai đại diện cho nơi nhận crypto trên một blockchain cụ thể, giống số tài khoản ngân hàng nhưng gắn với từng mạng lưới."],["on-chain-analysis","Phân tích on-chain","Phân tích on-chain là việc đọc dữ liệu công khai trên blockchain như giao dịch, số dư ví và dòng tiền ra vào sàn để hiểu hành vi của người tham gia thị trường."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"Báo đã gửi nhưng tiền chưa tới. Cần kiểm tra ở đâu?"},"coin":null,"tool":null,"cta":false},"travel-rule":{"slug":"travel-rule","cat":"regulation","en":"Travel rule","contentLocale":"vi","term":"Travel rule (quy tắc chuyển tiền)","aka":["travel rule","quy tắc travel rule","FATF Recommendation 16"],"short":"Travel rule là quy định yêu cầu các nhà cung cấp dịch vụ tài sản ảo gửi kèm thông tin người gửi và người nhận khi chuyển crypto giữa các tổ chức với nhau.","body":["Quy tắc này bắt nguồn từ Khuyến nghị số 16 của FATF, vốn áp dụng cho chuyển khoản ngân hàng, rồi được mở rộng sang tài sản ảo. Hướng dẫn của FATF đặt ngưỡng 1.000 USD hoặc EUR, nhưng mỗi quốc gia tự quyết định ngưỡng. Liên minh châu Âu áp dụng từ euro đầu tiên kể từ ngày 30 tháng 12 năm 2024.",["Trong thực tế, khi bạn rút từ sàn này sang sàn khác, sàn gửi có thể hỏi tên người nhận, sàn nhận là sàn nào, hoặc yêu cầu ",["xác nhận","block-confirmations"]," ví đích là ",["ví tự lưu ký","non-custodial-wallet"]," của chính bạn. Sàn nhận có thể giữ khoản nạp cho tới khi khớp được thông tin."],"Mỗi sàn dùng giao thức travel rule khác nhau và không phải cặp sàn nào cũng kết nối được với nhau. Vì vậy trước khi chuyển số tiền lớn, nên chuyển thử một khoản nhỏ và kiểm tra yêu cầu khai báo của cả hai bên."],"example":["Giả sử bạn rút 3.000 ",["USDT","usdt"]," từ sàn A ở châu Âu sang sàn B. Màn hình rút tiền hỏi ví nhận thuộc sàn nào và họ tên người nhận. Bạn chọn sàn B và điền tên mình đúng như trên hồ sơ ",["KYC","kyc"],". Nếu bạn ghi sai tên hoặc chọn nhầm là ví cá nhân, sàn B có thể tạm giữ 3.000 USDT và yêu cầu bổ sung thông tin. Nếu chuyển thử 20 USDT trước, bạn sẽ thấy ngay hai sàn có khớp được dữ liệu hay không."],"mistakes":["Khai sai tên người nhận hoặc chọn sai loại ví khi rút tiền, khiến khoản nạp bị treo.","Chuyển ngay số tiền lớn giữa hai sàn chưa từng chuyển qua lại.","Nghĩ rằng travel rule chỉ áp dụng cho khoản trên 1.000 USD ở mọi nơi."],"faq":[{"q":"Rút về ví cá nhân có bị travel rule không?","a":"Có thể. Nhiều sàn yêu cầu bạn xác nhận ví nhận là ví tự lưu ký của chính bạn, đôi khi kèm bước ký xác minh quyền sở hữu, tùy quy định nơi sàn hoạt động."},{"q":"Tiền bị giữ vì travel rule thì làm sao?","a":"Hãy mở thông báo trong ứng dụng sàn nhận và bổ sung đúng thông tin người gửi. Nếu cần, liên hệ hỗ trợ chính thức kèm TxID."}],"title":"Travel rule là gì? Quy tắc khi chuyển crypto giữa sàn","description":"Travel rule buộc sàn gửi kèm thông tin người gửi và nhận. Tìm hiểu ngưỡng FATF, quy định EU và cách tránh bị treo tiền.","related":[["kyc","KYC (xác minh danh tính khách hàng)","KYC là quy trình sàn giao dịch hoặc tổ chức tài chính xác minh danh tính người dùng bằng giấy tờ tùy thân, ảnh khuôn mặt và đôi khi là địa chỉ cư trú."],["aml","AML (phòng chống rửa tiền)","AML là tập hợp quy định và quy trình mà sàn giao dịch và tổ chức tài chính áp dụng để phát hiện, ngăn chặn và báo cáo hoạt động rửa tiền hoặc tài trợ khủng bố."],["vasp","VASP (nhà cung cấp dịch vụ tài sản ảo)","VASP là tổ chức cung cấp dịch vụ liên quan đến tài sản ảo cho người khác, như sàn giao dịch, dịch vụ lưu ký hoặc chuyển đổi crypto, và chịu các nghĩa vụ quản lý như KYC, AML."],["withdrawal-whitelist","Danh sách trắng rút tiền (Withdrawal whitelist)","Danh sách trắng rút tiền là tính năng bảo mật chỉ cho phép tài khoản sàn rút crypto đến những địa chỉ bạn đã lưu và xác minh trước."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Trước khi chuyển coin: Tuyệt đối không đoán mò những điểm này"},"coin":null,"tool":null,"cta":false},"spot-bitcoin-etf":{"slug":"spot-bitcoin-etf","cat":"regulation","en":"Spot bitcoin ETF","contentLocale":"vi","term":"ETF Bitcoin giao ngay (spot Bitcoin ETF)","aka":["spot Bitcoin ETF","ETF Bitcoin spot","quỹ ETF Bitcoin"],"short":"ETF Bitcoin giao ngay là quỹ hoán đổi danh mục niêm yết trên sàn chứng khoán, nắm giữ BTC thật và cho nhà đầu tư tiếp xúc với giá Bitcoin qua tài khoản chứng khoán.","body":[["Khác với ETF dựa trên ",["hợp đồng tương lai","futures-contract"],", ETF giao ngay mua và lưu ký ",["Bitcoin","bitcoin"]," thật thông qua một đơn vị lưu ký. Các ETF Bitcoin giao ngay tại Mỹ bắt đầu giao dịch vào tháng 1 năm 2024, với các nhà phát hành như BlackRock, Fidelity và nhiều công ty quản lý quỹ khác."],["Người mua chứng chỉ quỹ không sở hữu BTC trực tiếp, không có ",["khóa riêng tư","private-key"]," và không thể rút coin ra ví. Đổi lại, họ mua bán qua công ty chứng khoán quen thuộc, trong giờ giao dịch của sàn chứng khoán, và trả một mức phí quản lý hằng năm."],"Dòng tiền vào ra ETF được nhiều người theo dõi như chỉ báo nhu cầu của tổ chức. Khả năng mua ETF này phụ thuộc vào quốc gia bạn sống và công ty chứng khoán bạn dùng."],"example":"Giả sử một ETF Bitcoin giao ngay có phí quản lý 0,25% mỗi năm và bạn đầu tư tương đương 10.000 USD. Nếu giá BTC đứng yên cả năm, giá trị khoản đầu tư giảm khoảng 25 USD do phí. Nếu bạn tự mua 10.000 USD BTC trên sàn crypto với phí 0,1%, bạn trả khoảng 10 USD một lần nhưng phải tự bảo quản coin. Hai lựa chọn khác nhau ở phí, quyền sở hữu và trách nhiệm lưu ký.","mistakes":["Nghĩ mua ETF là đang sở hữu Bitcoin có thể rút về ví.","Bỏ qua phí quản lý cộng dồn khi nắm giữ nhiều năm.","Cho rằng dòng tiền ETF một ngày quyết định xu hướng giá."],"faq":[{"q":"ETF Bitcoin giao ngay khác ETF tương lai thế nào?","a":"ETF giao ngay nắm giữ BTC thật, còn ETF tương lai nắm hợp đồng futures và phải chuyển hợp đồng định kỳ, có thể làm lệch hiệu suất so với giá BTC."},{"q":"Người Việt Nam có mua được ETF Bitcoin Mỹ không?","a":"Phụ thuộc vào công ty môi giới bạn dùng và quy định về đầu tư ra nước ngoài. Hãy kiểm tra điều kiện mở tài khoản quốc tế và quy định hiện hành."}],"title":"ETF Bitcoin giao ngay là gì? Khác gì mua BTC trực tiếp","description":"Spot Bitcoin ETF nắm giữ BTC thật và giao dịch trên sàn chứng khoán. So sánh phí, quyền sở hữu và cách khác với mua BTC.","related":[["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) là đồng tiền mã hóa đầu tiên, ra đời năm 2009, chạy trên blockchain riêng dùng cơ chế bằng chứng công việc và có tổng cung tối đa cố định 21 triệu đồng."],["tokenized-stocks","Cổ phiếu token hóa (tokenized stocks)","Cổ phiếu token hóa là token đại diện cho giá trị của một cổ phiếu niêm yết như Apple hay Tesla, thường được bảo chứng bởi cổ phiếu thật do một đơn vị lưu ký nắm giữ."],["custodial-wallet","Ví lưu ký (Custodial wallet)","Ví lưu ký là ví mà một bên thứ ba, thường là sàn giao dịch, giữ khóa riêng tư thay bạn; bạn truy cập tài sản bằng tài khoản và mật khẩu thay vì seed phrase."],["market-capitalization","Vốn hóa thị trường (Market cap)","Vốn hóa thị trường (market cap) của một đồng tiền mã hóa là giá hiện tại nhân với nguồn cung lưu hành, cho biết tổng giá trị thị trường đang định cho lượng coin đang lưu thông."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"geo-restrictions":{"slug":"geo-restrictions","cat":"regulation","en":"Geo-restrictions (restricted regions)","contentLocale":"vi","term":"Giới hạn khu vực (geo-restrictions)","aka":["geo-restrictions","khu vực bị hạn chế","chặn quốc gia","restricted regions"],"short":"Giới hạn khu vực là danh sách quốc gia hoặc vùng lãnh thổ mà một sàn hay dịch vụ crypto không phục vụ hoặc chỉ phục vụ một phần sản phẩm, do yêu cầu pháp lý.","body":[["Mỗi sàn công bố danh sách khu vực bị hạn chế trong điều khoản dịch vụ. Một số nước bị chặn hoàn toàn, số khác chỉ bị chặn một số sản phẩm như ",["hợp đồng tương lai","futures-contract"],", ",["đòn bẩy","leverage"],", ",["staking","staking"]," hoặc token nhất định. Danh sách có thể thay đổi khi luật thay đổi."],["Sàn kiểm tra khu vực bằng địa chỉ IP, quốc tịch trên giấy tờ ",["KYC","kyc"]," và địa chỉ cư trú. Dùng VPN để vượt chặn thường vi phạm điều khoản, và khi bị phát hiện, sàn có thể yêu cầu đóng vị thế, chỉ cho rút tiền hoặc khóa tài khoản."],["Với ",["DEX","dex"],", giao diện web có thể chặn một số khu vực trong khi ",["hợp đồng thông minh","smart-contract"]," vẫn chạy trên chuỗi. Dù vậy, trách nhiệm tuân thủ luật nơi bạn sống vẫn thuộc về bạn."]],"example":"Giả sử bạn đang du lịch ở một nước nằm trong danh sách hạn chế phái sinh của sàn và mở ứng dụng để giao dịch. Bạn có vị thế long 0,5 BTC với đòn bẩy 5 lần. Ứng dụng cho phép đóng vị thế nhưng chặn mở lệnh mới vì IP thuộc khu vực bị hạn chế. Nếu biết trước, bạn có thể đặt sẵn lệnh cắt lỗ và chốt lời trước chuyến đi để không phải thao tác từ nơi bị chặn.","mistakes":["Dùng VPN để lách khu vực bị hạn chế, dẫn tới nguy cơ khóa tài khoản.","Khai địa chỉ cư trú khác với thực tế khi KYC.","Không đọc lại danh sách khu vực khi sàn cập nhật điều khoản."],"faq":[{"q":"Vì sao sàn chặn một số quốc gia?","a":"Do sàn chưa có giấy phép ở đó, luật cấm một số sản phẩm, hoặc vì lệnh trừng phạt quốc tế. Lý do khác nhau tùy từng khu vực."},{"q":"Đang ở nước bị hạn chế thì tiền trên sàn có mất không?","a":"Thường thì không, phần lớn sàn vẫn cho đóng vị thế và rút tiền. Tuy nhiên chính sách mỗi sàn khác nhau, hãy đọc điều khoản trước khi di chuyển."}],"title":"Geo-restrictions là gì? Khu vực bị sàn crypto hạn chế","description":"Giới hạn khu vực là danh sách quốc gia sàn crypto không phục vụ. Tìm hiểu cách sàn kiểm tra, rủi ro dùng VPN và cách xử lý.","related":[["kyc","KYC (xác minh danh tính khách hàng)","KYC là quy trình sàn giao dịch hoặc tổ chức tài chính xác minh danh tính người dùng bằng giấy tờ tùy thân, ảnh khuôn mặt và đôi khi là địa chỉ cư trú."],["vasp","VASP (nhà cung cấp dịch vụ tài sản ảo)","VASP là tổ chức cung cấp dịch vụ liên quan đến tài sản ảo cho người khác, như sàn giao dịch, dịch vụ lưu ký hoặc chuyển đổi crypto, và chịu các nghĩa vụ quản lý như KYC, AML."],["no-kyc-exchange","Sàn không KYC","Sàn không KYC là nơi cho phép giao dịch hoặc rút crypto mà không cần xác minh danh tính, thường trong một hạn mức nhất định hoặc thông qua mô hình phi tập trung."],["centralized-exchange","Sàn giao dịch tập trung (CEX)","Sàn giao dịch tập trung (CEX) là nền tảng do một công ty vận hành, giữ tài sản của người dùng và khớp lệnh mua bán trên sổ lệnh nội bộ, như Binance, OKX, Bybit hay Bitget."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC thực hiện như thế nào và ai mới là người nhận giấy tờ của bạn?"},"coin":null,"tool":"/exchanges","cta":false},"delisting":{"slug":"delisting","cat":"exchange-features","en":"Delisting","contentLocale":"vi","term":"Hủy niêm yết (delisting)","aka":["delist","delisting","hủy niêm yết","gỡ khỏi sàn"],"short":"Hủy niêm yết là việc sàn giao dịch ngừng hỗ trợ một token hoặc cặp giao dịch, thường kèm thời hạn để người dùng đóng vị thế, bán hoặc rút token ra ngoài.","body":[["Sàn định kỳ rà soát các token đã ",["niêm yết","token-listing"],". Lý do hủy niêm yết có thể là ",["thanh khoản","liquidity"]," thấp, đội ngũ ngừng phát triển, sự cố bảo mật, vi phạm quy định hoặc yêu cầu pháp lý tại một khu vực. Đôi khi chỉ một ",["cặp giao dịch","trading-pair"]," bị gỡ, còn token vẫn giao dịch với cặp khác."],["Thông báo thường nêu ba mốc: ngừng giao dịch, ngừng nạp và hạn chót rút. Sau mốc ngừng giao dịch, lệnh đang chờ bị hủy. ",["Hợp đồng tương lai","futures-contract"]," của token đó cũng thường bị đóng tự động ở một mức giá thanh toán."],["Giá token thường giảm mạnh khi có tin hủy niêm yết vì người dùng đồng loạt bán. Nếu bỏ lỡ hạn rút, bạn có thể phải liên hệ hỗ trợ, và một số sàn tự đổi token còn lại sang ",["stablecoin","stablecoin"]," theo quy định riêng."]],"example":["Giả sử bạn giữ 10.000 token DEF trên sàn, giá 0,08 ",["USDT","usdt"],", tổng giá trị 800 USDT. Sàn thông báo hủy niêm yết sau 7 ngày. Ngay sau tin, giá giảm 30% xuống 0,056 USDT, giá trị còn 560 USDT. Bạn có thể bán ngay, hoặc rút sang một sàn khác vẫn niêm yết DEF. Nếu phí rút là 50 DEF và sàn kia có thanh khoản tốt hơn, việc chuyển đi có thể đáng cân nhắc."],"mistakes":["Không đọc thông báo của sàn và để lỡ hạn chót rút token.","Mua token vừa bị thông báo hủy niêm yết vì thấy giá rẻ.","Quên rằng vị thế hợp đồng tương lai của token đó sẽ bị đóng tự động."],"faq":[{"q":"Token bị hủy niêm yết thì tiền có mất không?","a":"Không mất ngay. Bạn vẫn có thể bán trước hạn hoặc rút sang ví hay sàn khác. Rủi ro lớn nhất là giá giảm mạnh và thanh khoản cạn."},{"q":"Có nên mua token sắp bị hủy niêm yết?","a":"Thường rất rủi ro vì thanh khoản giảm dần và khó tìm nơi bán. Chỉ cân nhắc nếu bạn hiểu rõ dự án và có nơi giao dịch thay thế."}],"title":"Hủy niêm yết là gì? Làm gì khi token bị delist","description":"Delisting là khi sàn ngừng hỗ trợ một token. Tìm hiểu lý do, các mốc thời gian, ảnh hưởng tới giá và cách xử lý tài sản.","related":[["token-listing","Niêm yết token (listing)","Niêm yết token là việc một sàn giao dịch chính thức thêm một token vào danh sách để người dùng có thể nạp, rút và giao dịch với các cặp nhất định."],["liquidity","Thanh khoản (Liquidity)","Thanh khoản là mức độ dễ dàng mua hoặc bán một tài sản với số lượng lớn mà giá không bị đẩy đi nhiều."],["withdrawal-fee","Phí rút tiền (withdrawal fee)","Phí rút tiền là khoản phí sàn thu khi bạn chuyển crypto từ tài khoản sàn ra ví hoặc sàn khác, thường là một số coin cố định tùy theo mạng blockchain bạn chọn."],["rug-pull","Rug pull (Rút thảm)","Rug pull là khi đội ngũ dự án crypto đột ngột rút thanh khoản, bán tháo token hoặc biến mất cùng tiền của nhà đầu tư, khiến giá token gần như về 0."]],"lesson":null,"coin":null,"tool":"/activities","cta":false}});
